with src as (select *, date_format(start_date, 'yyyy-MM') as start_date_label from subscriptions where plan in ('basic', 'premium') and start_date >= '2024-02-07'), agg as (select month(start_date) as start_month, sum(case when plan = 'basic' then monthly_fee else 0 end) as basic_monthly_fee, round(avg(monthly_fee), 2) as avg_monthly_fee from src group by month(start_date)) select * from agg where basic_monthly_fee < 55;
